draw:
var F = p.force, r = p.radius, th = p.angle * Math.PI / 180;
var px = W * 0.30, py = H * 0.62;
var scale = (W * 0.42) / 0.5;
var ax = px + r * scale, ay = py;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

// pivot
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(px, py + 34); ctx.lineTo(px, py - 34); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(px, py, 4, 0, 6.2832); ctx.fill();
ctx.fillText("pivot", px - 16, py + 50);

// the rigid bar
ctx.strokeStyle = C.figure;
ctx.lineWidth = 5;
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px + 0.5 * scale, py); ctx.stroke();

// r marker
ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(px, py + 22); ctx.lineTo(ax, py + 22); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("r = " + r.toFixed(2) + " m", (px + ax) / 2 - 26, py + 36);

// force arrow from application point
var L = 58 + F * 1.1;
var fx = ax + L * Math.cos(-th), fy = ay + L * Math.sin(-th);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2.5;
ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(fx, fy); ctx.stroke();
var hw = 6;
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.moveTo(fx, fy);
ctx.lineTo(fx - 12 * Math.cos(-th) + hw * Math.sin(-th), fy - 12 * Math.sin(-th) - hw * Math.cos(-th));
ctx.lineTo(fx - 12 * Math.cos(-th) - hw * Math.sin(-th), fy - 12 * Math.sin(-th) + hw * Math.cos(-th));
ctx.closePath(); ctx.fill();
ctx.fillText("F = " + F.toFixed(0) + " N", fx + 6, fy - 4);

// line of action, extended both ways
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.setLineDash([2, 5]);
ctx.beginPath();
ctx.moveTo(ax - 240 * Math.cos(-th), ay - 240 * Math.sin(-th));
ctx.lineTo(ax + 240 * Math.cos(-th), ay + 240 * Math.sin(-th));
ctx.stroke();
ctx.setLineDash([]);

// perpendicular from pivot to line of action = lever arm
var vx = Math.cos(-th), vy = Math.sin(-th);
var wx = px - ax, wy = py - ay;
var proj = wx * vx + wy * vy;
var footx = ax + proj * vx, footy = ay + proj * vy;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.setLineDash([5, 4]);
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(footx, footy); ctx.stroke();
ctx.setLineDash([]);
var lever = Math.abs(r * Math.sin(th));
ctx.fillStyle = C.figure;
ctx.fillText("lever arm r sin" + "θ = " + lever.toFixed(3) + " m", 10, 20);

// angle label
ctx.fillStyle = C.ink;
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.arc(ax, ay, 24, -th, 0, th < 0); ctx.stroke();
ctx.fillText("θ = " + p.angle.toFixed(0) + "°", ax + 28, ay - 10);

var tau = r * F * Math.sin(th);
out.note = "torque = r F sin(theta) = " + r.toFixed(2) + " x " + F.toFixed(0) + " x " + Math.sin(th).toFixed(3) + " = " + tau.toFixed(2) + " N m";

var g = 9.8;
var m = p.block, M = p.pulley, R = 0.20;
var I = 0.5 * M * R * R;
var a = m * g / (m + 0.5 * M);
var T = m * (g - a);
var alpha = a / R;

var cx = W * 0.36, cy = H * 0.30, rad = Math.min(W, H) * 0.14;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// support
ctx.strokeStyle = C.rule; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(cx, cy - rad); ctx.lineTo(cx, cy - rad - 24); ctx.stroke();
ctx.beginPath(); ctx.moveTo(cx - 30, cy - rad - 24); ctx.lineTo(cx + 30, cy - rad - 24); ctx.stroke();

// fall distance, looping
var cycle = 1.6;
var tt = t % cycle;
var drop = 0.5 * a * tt * tt;
var dpix = drop * (H * 0.30);
if (dpix > H * 0.34) dpix = H * 0.34;
var theta = 0.5 * alpha * tt * tt;

// pulley
ctx.strokeStyle = C.figure; ctx.lineWidth = 3;
ctx.beginPath(); ctx.arc(cx, cy, rad, 0, 6.2832); ctx.stroke();
ctx.strokeStyle = C.faint; ctx.lineWidth = 2;
for (var k = 0; k < 4; k++) {
  var an = theta + k * Math.PI / 4;
  ctx.beginPath();
  ctx.moveTo(cx - rad * Math.cos(an), cy - rad * Math.sin(an));
  ctx.lineTo(cx + rad * Math.cos(an), cy + rad * Math.sin(an));
  ctx.stroke();
}
ctx.fillStyle = C.ink;
ctx.fillText("pulley M = " + M.toFixed(1) + " kg", cx - rad - 4, cy - rad - 32);

// cord and block
var bx = cx + rad, by = cy + 40 + dpix;
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(bx, cy); ctx.lineTo(bx, by); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillRect(bx - 20, by, 40, 30);
ctx.fillStyle = C.paper;
ctx.fillText(m.toFixed(1) + " kg", bx - 15, by + 19);

// force labels on block
ctx.fillStyle = C.accent;
ctx.fillText("T = " + T.toFixed(2) + " N", bx + 26, by + 2);
ctx.fillStyle = C.ink;
ctx.fillText("mg = " + (m * g).toFixed(2) + " N", bx + 26, by + 44);
ctx.strokeStyle = C.ink; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(bx, by + 30); ctx.lineTo(bx, by + 52); ctx.stroke();
ctx.beginPath(); ctx.moveTo(bx, by + 56); ctx.lineTo(bx - 4, by + 48); ctx.lineTo(bx + 4, by + 48); ctx.closePath(); ctx.fill();

// bar chart comparison with free fall
var gx = W * 0.72, gy0 = H * 0.80, hmax = H * 0.5;
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(gx - 30, gy0); ctx.lineTo(gx + 90, gy0); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillRect(gx - 20, gy0 - hmax, 28, hmax);
ctx.fillStyle = C.accent;
ctx.fillRect(gx + 30, gy0 - hmax * a / g, 28, hmax * a / g);
ctx.fillStyle = C.ink;
ctx.fillText("g", gx - 12, gy0 + 14);
ctx.fillText("a", gx + 40, gy0 + 14);

out.note = "a = " + a.toFixed(2) + " m/s^2, T = " + T.toFixed(2) + " N, alpha = " + alpha.toFixed(1) + " rad/s^2 (I = " + I.toFixed(3) + " kg m^2)";

var g = 9.8;
var L = p.length;
var th0 = p.start * Math.PI / 180;

// integrate: alpha = (3g / 2L) cos(theta), theta measured up from the ground
var th = th0, om = 0, dt = 0.0008, tt = t % 3.0, n = Math.floor(tt / dt);
if (n > 4000) n = 4000;
for (var i = 0; i < n; i++) {
  if (th <= 0) { th = 0; break; }
  om = om + (3 * g / (2 * L)) * Math.cos(th) * dt;
  th = th - om * dt;
}
if (th < 0) th = 0;

var px = W * 0.22, py = H * 0.82;
var scale = (W * 0.6) / 1.6;
var tipx = px + L * scale * Math.cos(th);
var tipy = py - L * scale * Math.sin(th);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// ground
ctx.strokeStyle = C.rule; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(16, py); ctx.lineTo(W - 16, py); ctx.stroke();

// start position, faint
ctx.strokeStyle = C.faint; ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(px, py);
ctx.lineTo(px + L * scale * Math.cos(th0), py - L * scale * Math.sin(th0));
ctx.stroke();

// rod
ctx.strokeStyle = C.figure; ctx.lineWidth = 6;
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(tipx, tipy); ctx.stroke();

// centre of mass and its weight
var cmx = px + 0.5 * L * scale * Math.cos(th);
var cmy = py - 0.5 * L * scale * Math.sin(th);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(cmx, cmy, 4, 0, 6.2832); ctx.fill();
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(cmx, cmy); ctx.lineTo(cmx, cmy + 32); ctx.stroke();
ctx.beginPath(); ctx.moveTo(cmx, cmy + 38); ctx.lineTo(cmx - 4, cmy + 29); ctx.lineTo(cmx + 4, cmy + 29); ctx.closePath(); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("Mg acts at L/2", cmx + 8, cmy + 26);

// pivot
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(px, py, 5, 0, 6.2832); ctx.fill();
ctx.fillText("hinge", px - 34, py + 16);
ctx.fillText("lever arm = (L/2) cos" + "θ = " + (0.5 * L * Math.cos(th)).toFixed(3) + " m", 14, 20);

var alpha = (3 * g / (2 * L)) * Math.cos(th);
var vtip = om * L;
out.note = "theta = " + (th * 180 / Math.PI).toFixed(1) + " deg, alpha = " + alpha.toFixed(2) + " rad/s^2, omega = " + om.toFixed(2) + " rad/s, tip speed = " + vtip.toFixed(2) + " m/s";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var tableY = H * 0.34, tableX0 = W * 0.06, tableX1 = W * 0.52;
ctx.strokeStyle = C.rule; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(tableX0, tableY); ctx.lineTo(tableX1, tableY); ctx.stroke();

// block on table
var bx = W * 0.20, bw = 54, bh = 34;
ctx.fillStyle = C.figure;
ctx.fillRect(bx, tableY - bh, bw, bh);
ctx.fillStyle = C.paper;
ctx.fillText("m1", bx + 18, tableY - 13);

function arrow(x0, y0, x1, y1, col, label, lx, ly) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var dx = x1 - x0, dy = y1 - y0, len = Math.sqrt(dx * dx + dy * dy);
  var ux = dx / len, uy = dy / len;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 9 * ux + 5 * uy, y1 - 9 * uy - 5 * ux);
  ctx.lineTo(x1 - 9 * ux - 5 * uy, y1 - 9 * uy + 5 * ux);
  ctx.closePath(); ctx.fill();
  ctx.fillText(label, lx, ly);
}

var cyb = tableY - bh / 2;
arrow(bx + bw, cyb, bx + bw + 52, cyb, C.accent, "T1", bx + bw + 20, cyb - 8);
arrow(bx, cyb, bx - 46, cyb, C.ink, "friction", bx - 74, cyb - 8);
arrow(bx + bw / 2, tableY - bh, bx + bw / 2, tableY - bh - 40, C.ink, "N", bx + bw / 2 + 6, tableY - bh - 24);
arrow(bx + bw / 2, tableY - bh / 2, bx + bw / 2, tableY + 30, C.ink, "m1 g", bx + bw / 2 + 6, tableY + 22);

// pulley
var cx = W * 0.60, cy = tableY - bh / 2, rad = Math.min(W, H) * 0.10;
ctx.strokeStyle = C.figure; ctx.lineWidth = 3;
ctx.beginPath(); ctx.arc(cx, cy, rad, 0, 6.2832); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(cx, cy, 3, 0, 6.2832); ctx.fill();
ctx.fillText("pulley: I, radius R", cx - rad, cy - rad - 12);

// cords
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(bx + bw + 6, cy - rad); ctx.lineTo(cx, cy - rad); ctx.stroke();
ctx.beginPath(); ctx.moveTo(cx + rad, cy); ctx.lineTo(cx + rad, cy + H * 0.30); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("T1 pulls back here", cx - rad - 10, cy - rad - 30);
ctx.fillText("T2", cx + rad + 8, cy + 30);

// hanging block
var hy = cy + H * 0.30;
ctx.fillStyle = C.figure;
ctx.fillRect(cx + rad - 24, hy, 48, 34);
ctx.fillStyle = C.paper;
ctx.fillText("m2", cx + rad - 10, hy + 22);
arrow(cx + rad, hy + 34, cx + rad, hy + 70, C.ink, "m2 g", cx + rad + 8, hy + 60);

ctx.fillStyle = C.ink;
ctx.fillText("T2 > T1: the difference is what spins the pulley", 12, H - 10);
